import re
from collections import deque
from decimal import Decimal


class ExpressionCalculator:
    OPERAND_SEPARATOR = ','
    NEGATIVE_SIGN = '~'
    MAPPED_DIVISION_FOR_MODULO = '/'

    def __init__(self):
        self.postfix_stack = deque()
        self.operat_priority = [0, 3, 2, 1, -1, 1, 0, 2]

    def calculate(self, expression):
        self.prepare(self.transform(expression))

        return self._evaluate_postfix()

    def _evaluate_postfix(self):
        result_stack = deque()
        self.postfix_stack.reverse()

        while self.postfix_stack:
            current_op = self.postfix_stack.pop()
            if not self.is_operator(current_op):
                result_stack.append(self._normalize_negatives(current_op))
            else:
                second_value = result_stack.pop()
                first_value = result_stack.pop()

                self._push_calculation_result(result_stack, first_value, second_value, current_op)

        return float(eval("*".join(result_stack)))

    def _normalize_negatives(self, value):
        return value.replace(self.NEGATIVE_SIGN, "-")

    def _push_calculation_result(self, result_stack, first_value, second_value, current_op):
        first_value = self._normalize_negatives(first_value)
        second_value = self._normalize_negatives(second_value)
        temp_result = self._calculate(first_value, second_value, current_op)
        result_stack.append(str(temp_result))

    def prepare(self, expression):
        op_stack = deque([self.OPERAND_SEPARATOR])
        arr = list(expression)
        current_index = 0
        self._process_operands_and_operators(arr, op_stack)

        while op_stack[-1] != self.OPERAND_SEPARATOR:
            self.postfix_stack.append(str(op_stack.pop()))

    def _process_operands_and_operators(self, arr, op_stack):
        current_index = 0
        count = 0

        for i, current_op in enumerate(arr):
            if self.is_operator(current_op):
                if count > 0:
                    self.postfix_stack.append("".join(arr[current_index: current_index + count]))
                peek_op = op_stack[-1]
                if current_op == ')':
                    self._pop_until_open_paren(op_stack)
                    op_stack.pop()
                else:
                    self._push_operands_of_higher_or_equal_priority(current_op, peek_op, op_stack)
                    op_stack.append(current_op)

                count = 0
                current_index = i + 1
            else:
                count += 1

        if count > 1 or (count == 1 and not self.is_operator(arr[current_index])):
            self.postfix_stack.append("".join(arr[current_index: current_index + count]))

    def _pop_until_open_paren(self, op_stack):
        while op_stack[-1] != '(':
            self.postfix_stack.append(str(op_stack.pop()))

    def _push_operands_of_higher_or_equal_priority(self, current_op, peek_op, op_stack):
        while current_op != '(' and peek_op != self.OPERAND_SEPARATOR and self.compare(current_op, peek_op):
            self.postfix_stack.append(str(op_stack.pop()))
            peek_op = op_stack[-1]

    @staticmethod
    def is_operator(c):
        return c in {'+', '-', '*', '/', '(', ')', '%'}

    def compare(self, cur, peek):
        if cur == '%':
            cur = self.MAPPED_DIVISION_FOR_MODULO
        if peek == '%':
            peek = self.MAPPED_DIVISION_FOR_MODULO
        return self.operat_priority[ord(peek) - 40] >= self.operat_priority[ord(cur) - 40]

    @staticmethod
    def _calculate(first_value, second_value, current_op):
        if current_op == '+':
            return Decimal(first_value) + Decimal(second_value)
        elif current_op == '-':
            return Decimal(first_value) - Decimal(second_value)
        elif current_op == '*':
            return Decimal(first_value) * Decimal(second_value)
        elif current_op == '/':
            return Decimal(first_value) / Decimal(second_value)
        elif current_op == '%':
            return Decimal(first_value) % Decimal(second_value)
        else:
            raise ValueError("Unexpected operator: {}".format(current_op))

    @staticmethod
    def transform(expression):
        expression = re.sub(r"\s+", "", expression)
        expression = re.sub(r"=$", "", expression)
        arr = list(expression)

        for i, c in enumerate(arr):
            if c == '-':
                if i == 0:
                    arr[i] = '~'
                else:
                    prev_c = arr[i - 1]
                    if prev_c in {'+', '-', '*', '/', '(', 'E', 'e'}:
                        arr[i] = '~'

        if arr[0] == '~' and (len(arr) > 1 and arr[1] == '('):
            arr[0] = '-'
            return "0" + "".join(arr)
        else:
            return "".join(arr)
